#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Crea static/clientes.html y agrega el tile "Clientes" al menu (visible
para todos los usuarios, no solo gerentes).
Corre DESPUES de creditos_backend.py y creditos_pagos_frontend.py
Uso: cd ~/inventario && python3 creditos_frontend_pagina.py
"""
import os, base64

BASE = os.path.expanduser('~/inventario')
STATIC = os.path.join(BASE, 'static')

CLIENTES_HTML_B64 = ''

# ================================================================
# 1. Crear static/clientes.html
# ================================================================
print("1. Creando static/clientes.html...")
clientes_path = os.path.join(STATIC, 'clientes.html')
with open(clientes_path, 'wb') as f:
    f.write(base64.b64decode(CLIENTES_HTML_B64))
print("   OK clientes.html creado (" + str(os.path.getsize(clientes_path)) + " bytes)")

# ================================================================
# 2. Agregar tile "Clientes" al menu (visible para TODOS, sin la
#    clase solo-gerente, ya que cajeros tambien manejan cobros/abonos)
# ================================================================
print("2. Agregando tile de Clientes al menu...")
menu_path = os.path.join(STATIC, 'menu.html')
msrc = open(menu_path, encoding='utf-8').read()

if 'href="/clientes"' in msrc:
    print("   * El tile ya existia, se omite")
else:
    tile = '''  <a class="menu-btn" href="/clientes">
    <div class="icon icon-pagos">👥</div>
    <div class="menu-text">
      <div class="menu-title">Clientes</div>
      <div class="menu-desc">Ventas a crédito, saldos y abonos</div>
    </div>
    <div class="arrow">›</div>
  </a>

'''
    marcador = '<a class="menu-btn" href="/pagos">'
    if marcador in msrc:
        # Insertar despues del bloque completo de "Punto de venta"
        idx = msrc.find(marcador)
        fin_bloque = msrc.find('</a>', idx) + len('</a>')
        msrc = msrc[:fin_bloque] + '\n\n' + tile.rstrip('\n') + msrc[fin_bloque:]
        open(menu_path, 'w', encoding='utf-8').write(msrc)
        print("   OK tile agregado (despues de Punto de venta)")
    else:
        print("   ADVERTENCIA: no se encontro el marcador de Punto de venta")
        print("   Agrega manualmente un enlace a /clientes en el menu")

print()
print("=" * 55)
print("Reiniciando el servicio...")
os.system("sudo systemctl restart inventario")
print("Listo. Entra a Menu -> Clientes para probarlo.")
